        [86964] = { -- For Gold and Glory! : https://wowhead.com/forever/quest=86964/for-gold-and-glory
            [questKeys.name] = "For Gold and Glory!",
            [questKeys.finishedBy] = {{237820}},
            [questKeys.requiredLevel] = 60,
